/* ---------- 여가구역: 하루 한 번 6곳 중 한 곳에서 버프를 받는다. 이후에는 분위기 묘사만 나온다 ---------- */
const hasJong = s => { const c = String(s).charCodeAt(String(s).length - 1) - 0xAC00; return c >= 0 && c < 11172 && c % 28 !== 0; };
const JS = (s, a, b) => s + (hasJong(s) ? a : b); // JS('민준','이','가') -> 민준이 / JS('수아','이','가') -> 수아가
const MAIN_STAT_BONUS = 2, SUB_STAT_BONUS = 1; // 프로필 이능력의 주·부 스탯 보너스
const LEISURE_MS = 8 * 3600 * 1000; // 여가 버프 지속 시간
const LEISURE = {
  '배팅장': { stat: 'str', icon: 'sports_baseball', desc: '쇠 배트를 힘껏 휘둘러 어깨가 후련하다. 근력 +2',
    info: '타석에 서서 공을 힘껏 때려 냅니다. 팔과 어깨가 후련해집니다.',
    solo: ['타석에 서서 배트를 고쳐 쥐었다. 기계가 쏘아 낸 공이 쐐애액 소리를 내며 날아든다. 딱! 하는 소리와 함께 공이 철망 높이 솟았다.', '헛스윙. 두 번째도 헛스윙. 세 번째, 눈을 부릅뜨고 휘두르자 공이 정확히 중심에 맞았다. 손바닥이 얼얼한데 기분이 좋다.', '구속을 한 단계 올렸다. 공이 눈앞을 스치듯 지나간다. 호흡을 가다듬고 다음 공을 기다렸다.', '배트를 어깨에 걸치고 숨을 골랐다. 전광판에 점수가 올라가는 걸 멍하니 쳐다보다 슬며시 웃음이 났다.', '철망 너머로 공이 날아가는 모습이 시원하다. 오늘 쌓인 일들이 공과 함께 날아간 기분이다.'],
    p2: (a) => [`${JS(a, '이', '가')} 옆 타석에서 먼저 휘둘렀다. "자, 이번엔 네 차례야!" 번갈아 공을 치며 점수를 겨뤘다.`, `${JS(a, '과', '와')} 나란히 타석에 섰다. 서로의 헛스윙에 웃음이 터졌다.`, `${a}에게 자세를 봐 달라고 했다. "팔꿈치를 조금만 올려 봐." 시키는 대로 하자 공이 시원하게 뻗었다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이 타석을 돌아가며 쳤다. 마지막에 가장 멀리 보낸 사람이 음료수를 사기로 했다.`, `${JS(a, '이', '가')} 홈런 판정을 받자 ${JS(b, '이', '가')} 박수를 치며 환호했다. 곧 셋의 내기가 뜨거워졌다.`, `타석 세 개가 나란히 울려 퍼졌다. ${a}, ${b}, 그리고 당신. 누구 공이 가장 멀리 가는지 겨뤘다.`],
    p4: (a, b, c) => [`네 사람이 타석 하나씩 차지하고 동시에 휘둘렀다. ${a}, ${b}, ${c}의 환호성이 철망을 흔든다.`, `${a}·${b}·${c}와 함께 팀을 나눠 점수를 겨뤘다. 마지막 공 하나에 모두의 시선이 쏠렸다.`, `${JS(c, '이', '가')} 연속 헛스윙을 하자 ${a}, ${b}까지 배를 잡고 웃었다. 결국 넷이 함께 마지막 라운드를 돌았다.`] },
  '게임센터': { stat: 'agi', icon: 'sports_esports', desc: '오락기 앞에서 손놀림이 날래졌다. 민첩 +2',
    info: '오락기와 리듬 게임이 가득한 곳입니다. 손놀림이 빨라집니다.',
    solo: ['동전을 넣자 화면이 번쩍였다. 레버를 쥔 손이 땀으로 축축하다. 마지막 라운드, 손가락이 건반 위를 날았다.', '리듬 게임 발판 위에서 정신없이 스텝을 밟았다. 콤보가 끊기지 않았다. 숨이 차오르는데 멈출 수가 없다.', '인형 뽑기 집게가 아슬아슬하게 인형을 들어 올렸다. 떨어지기 직전, 출구 위에서 가까스로 놓였다. 손에 쥔 인형이 묵직하다.', '레이싱 게임 시트에 앉아 핸들을 꺾었다. 마지막 코너를 가장 빠르게 돌고 1등으로 들어왔다.', '두더지 게임 망치를 쥐었다. 튀어나오는 두더지들을 하나하나 정확하게 눌렀다. 점수가 쑥쑥 오른다.'],
    p2: (a) => [`${JS(a, '과', '와')} 대전 오락기에 나란히 앉았다. 마지막 한 방에 화면이 번쩍이고, 승자는 의기양양하게 어깨를 으쓱였다.`, `${JS(a, '이', '가')} 리듬 게임 발판에 올라섰다. "같이 하자!" 둘이 박자를 맞춰 스텝을 밟았다.`, `인형 뽑기 앞에서 ${a}에게 조종을 맡겼다. 집게가 인형을 번쩍 들어 올리자 둘이 동시에 환호했다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이 레이싱 게임에서 순위를 겨뤘다. 마지막 직선에서 순위가 뒤집히자 비명 같은 환호가 터졌다.`, `${JS(a, '이', '가')} 인형을 뽑는 동안 ${JS(b, '이', '가')} 응원 박수를 보냈다. 인형은 결국 셋이 나눠 가졌다.`, `셋이서 두더지 게임 점수를 겨뤘다. ${a}의 망치질이 가장 빨랐지만, 마지막 한 마리는 당신이 잡았다.`],
    p4: (a, b, c) => [`네 사람이 둘씩 편을 갈라 대전 오락을 했다. ${a}, ${b}, ${c}의 야유와 환호가 오락기 소음 속에 뒤섞인다.`, `${a}·${b}·${c}와 리듬 게임 판 위에서 단체 스텝을 맞췄다. 마지막 콤보에서 모두가 동시에 소리쳤다.`, `동전이 바닥날 때까지 넷이서 오락기를 돌아다녔다. 손에는 인형과 경품권이 한가득이다.`] },
  '도서관': { stat: 'int', icon: 'local_library', desc: '조용한 서가에서 머리가 맑아졌다. 지능 +2',
    info: '조용한 서가가 이어진 도서관입니다. 머리가 맑아집니다.',
    solo: ['서가 사이를 천천히 걸으며 손끝으로 책등을 훑었다. 종이 냄새가 코끝에 감돈다. 마음이 가라앉는다.', '창가 자리에 앉아 책을 펼쳤다. 한 장, 두 장. 어느새 해가 한참 기울어 있었다.', '오래된 지도집을 발견했다. 지상의 지형이 손으로 그려진 페이지를 오래 들여다보았다.', '사서가 조용히 지나가며 눈인사를 건넸다. 당신은 속삭이듯 고개를 숙이고 다시 책으로 돌아갔다.', '읽다 만 구절에 밑줄 대신 눈길을 오래 두었다. 이해가 되는 순간, 머릿속이 환해졌다.'],
    p2: (a) => [`${JS(a, '과', '와')} 마주 앉아 각자 책을 펼쳤다. 가끔 눈이 마주치면 소리 없이 웃었다.`, `${JS(a, '이', '가')} 책 한 권을 슬며시 밀어 주었다. "이거 재밌어." 속삭임이 서가에 낮게 퍼졌다.`, `${a}에게 모르는 대목을 속삭이며 물었다. ${a}의 설명을 듣자 막혔던 부분이 풀렸다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이 한 테이블에 둘러앉았다. 각자 다른 책을 읽다가, 서로 읽은 대목을 쪽지로 주고받았다.`, `${JS(a, '이', '가')} 책을 꺼내 들고 ${b}에게 쉿 하고 입에 손가락을 댔다. 소리 죽인 웃음이 셋 사이에 번졌다.`, `책 한 권을 셋이서 돌려 읽었다. 마지막 장을 덮자 서로 말없이 고개를 끄덕였다.`],
    p4: (a, b, c) => [`네 사람이 긴 열람 테이블에 나란히 앉았다. ${a}, ${b}, ${c}의 책장 넘기는 소리가 합창처럼 겹친다.`, `${a}·${b}·${c}와 함께 퀴즈 책을 펼쳐 놓고 소리 죽여 문제를 맞혔다. 정답이 나올 때마다 책상 밑으로 주먹을 쥐었다.`, `사서의 눈총에 넷이 동시에 입을 틀어막았다. 그리고 한참을 어깨가 들썩이도록 웃음을 참았다.`] },
  '사우나': { stat: 'wil', icon: 'hot_tub', desc: '뜨거운 열기 속에서 마음이 단단해졌다. 의지 +2',
    info: '뜨끈한 열기와 냉탕이 있는 사우나입니다. 마음이 단단해집니다.',
    solo: ['한증막 문을 열자 후끈한 열기가 얼굴을 덮었다. 이를 악물고 앉아 땀이 맺히기를 기다렸다. 그리고 찬물에 풍덩.', '모래시계가 다 떨어질 때까지 버텼다. 땀이 흘러내리는데 머릿속은 오히려 고요하다.', '냉탕에 어깨까지 잠겼다. 숨이 확 멎었다가 길게 내쉬자 온몸이 새로 태어난 듯 상쾌하다.', '수건을 양머리로 말고 앉았다. 천장에서 물방울이 똑, 똑 떨어지는 소리만 들린다.', '식혜 한 잔을 들이켰다. 시원함이 목을 타고 내려가자 하루의 피로가 녹아내렸다.'],
    p2: (a) => [`${JS(a, '과', '와')} 나란히 한증막에 앉았다. "누가 더 오래 버티나 보자." 서로 눈빛을 주고받으며 땀만 뻘뻘 흘렸다.`, `${JS(a, '이', '가')} 식혜 두 잔을 들고 왔다. 말없이 건배를 하고 단숨에 비웠다.`, `${a}의 양머리 수건이 우스꽝스러워 웃음이 터졌다. 뜨거운 공기 속에서 둘 다 숨이 넘어갈 듯 웃었다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이서 누가 오래 버티나 내기를 했다. ${JS(a, '이', '가')} 먼저 뛰쳐나가자 둘이 박수를 쳤다.`, `냉탕에 셋이 동시에 뛰어들었다. 물보라가 튀고 비명이 울려 퍼졌다.`, `셋이 평상에 둘러앉아 삶은 달걀을 까 먹었다. ${JS(b, '이', '가')} 소금을 건네주었다.`],
    p4: (a, b, c) => [`네 사람이 한증막 한 줄에 앉았다. ${a}, ${b}, ${c}의 땀 흘린 얼굴이 서로 웃기다.`, `${a}·${b}·${c}와 함께 마지막 한 명이 남을 때까지 버티기를 했다. 끝까지 남은 이는 의기양양하게 식혜를 받아 들었다.`, `넷이서 평상에 드러누웠다. 아무 말도 필요 없다. 천장의 선풍기 소리만 들린다.`] },
  '영화관': { stat: 'sen', icon: 'movie', desc: '영화 속에 푹 빠져 감각이 예민해졌다. 감각 +2',
    info: '어두운 상영관에서 영화를 봅니다. 감각이 예민해집니다.',
    solo: ['불이 꺼지고 스크린이 밝아졌다. 팝콘 한 알을 입에 넣으며 화면 속 세계로 빠져들었다.', '엔딩 크레딧이 올라가는데 일어나기 싫다. 잔향처럼 남은 음악이 귓가를 맴돈다.', '옛날 흑백 영화를 틀어 주고 있었다. 지직거리는 화면 속에서 배우가 웃는다. 그 표정을 오래 바라보았다.', '코미디 영화에서 혼자 크게 웃어 버렸다. 주변이 힐끔 보았지만 곧 따라 웃었다.', '조용한 장면 속에서 팝콘 씹는 소리가 너무 커서 숨을 죽였다. 그러다 혼자 웃음이 났다.'],
    p2: (a) => [`${JS(a, '과', '와')} 나란히 앉아 팝콘을 나눠 먹었다. 손이 맞닿아 서로 멋쩍게 웃었다.`, `영화가 슬픈 대목에 접어들자 ${JS(a, '이', '가')} 슬쩍 눈가를 훔쳤다. 못 본 척 팝콘을 건넸다.`, `영화가 끝나고 ${a}${hasJong(a) ? '과' : '와'} 한참 감상을 주고받았다. 같은 장면에서 다른 걸 느꼈다는 게 신기했다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이 나란히 앉았다. 팝콘 통이 오가는 사이, 공포 장면에서 셋 다 동시에 몸을 움찔했다.`, `상영이 끝나자 셋이 서로 다른 결말 해석을 내놓았다. ${a}의 해석이 가장 그럴듯했다.`, `${JS(b, '이', '가')} 몰래 가져온 간식이 스크린 불빛에 반짝였다. 셋이 소리 죽여 나눠 먹었다.`],
    p4: (a, b, c) => [`네 사람이 한 줄에 나란히 앉았다. ${a}, ${b}, ${c}의 숨죽인 옆모습이 스크린 불빛에 물든다.`, `${a}·${b}·${c}와 함께 시끌벅적한 코미디를 봤다. 네 명이 동시에 웃음을 터뜨려 극장이 들썩였다.`, `엔딩이 끝나고 넷이 한동안 말이 없었다. 마침내 ${JS(c, '이', '가')} 입을 열었다. "…진짜 좋았다."`] },
  '사진관': { stat: 'luk', icon: 'photo_camera', desc: '찰칵, 좋은 기운이 담겼다. 행운 +2',
    info: '추억을 사진으로 남기는 사진관입니다. 좋은 기운이 따릅니다.',
    solo: ['조명이 켜지고 셔터 소리가 울렸다. 어색하게 지은 미소가 의외로 그럴듯하게 찍혔다.', '소품 상자에서 우스꽝스러운 안경을 골라 썼다. 거울 속 모습이 낯설어서 웃음이 났다.', '인화된 사진을 손에 들고 한참 바라보았다. 사진 속 나는 생각보다 괜찮은 얼굴이었다.', '배경 천을 바꿔 가며 여러 컷을 찍었다. 마지막 한 장이 유독 마음에 들었다.', '사진사가 "자연스럽게요" 하고 외치자 오히려 더 굳었다. 그러다 웃음이 터진 순간 찰칵!'],
    p2: (a) => [`${JS(a, '과', '와')} 어깨를 나란히 하고 카메라 앞에 섰다. 찰칵! 서로 눈이 반쯤 감긴 사진이 나왔지만 오히려 마음에 든다.`, `${JS(a, '이', '가')} 소품 모자를 씌워 주었다. 둘이 같은 포즈를 취하고 한 장을 남겼다.`, `인화된 사진 두 장을 ${a}과 하나씩 나눠 가졌다. 서로의 사진을 지갑에 꽂아 두기로 했다.`],
    p3: (a, b) => [`${a}, ${b}${hasJong(b) ? '과' : '와'} 셋이 몸을 붙이고 카메라 앞에 섰다. 사진사가 "하나 둘 셋!" 하자 셋이 동시에 브이를 했다.`, `${JS(a, '이', '가')} 포즈를 지휘했다. "당신은 가운데, ${b}${hasJong(b) ? '은' : '는'} 그 옆!" 어색한 구도가 그대로 한 장의 추억이 되었다.`, `인화된 사진 세 장을 나눠 가졌다. 모두 조금씩 다르게 웃고 있어서 다시 웃음이 났다.`],
    p4: (a, b, c) => [`좁은 사진관 배경 앞에 넷이 빽빽이 모였다. ${a}, ${b}, ${c}의 어깨가 서로 닿는다. 찰칵!`, `${a}·${b}·${c}와 함께 소품을 돌려 쓰며 단체 사진을 연달아 찍었다. 마지막 컷은 모두 점프한 장면이 걸렸다.`, `네 장의 사진이 인화되었다. 아무도 같은 표정이 아니라서 다 같이 웃었다. 사진은 오래 기억에 남을 것이다.`] }
};
const LEISURE_IDS = Object.keys(LEISURE);
Object.entries(LEISURE).forEach(([id, l]) => {
  const bn = `여가 · ${id}`;
  BUFFS[bn] = { type: 'buff', icon: l.icon, desc: l.desc, mods: { [l.stat]: 2 }, ms: LEISURE_MS };
  ACTIONS[id] = { kind: 'leisure', icon: l.icon, label: `${id} (${STAT_DEFS.find(d => d.key === l.stat).name})`, title: id, action: `${l.info} 하루에 한 번만 버프(${STAT_DEFS.find(d => d.key === l.stat).name} +2, 8시간)를 받을 수 있고, 이후에는 분위기만 즐길 수 있습니다.`, buff: bn };
});

