DANGER_ZONES.forEach(z => z.terrains.forEach(t => { (NEW_GATHER[`${z.id}:${t.name}`] || []).forEach(n => { if (!t.gather.includes(n)) t.gather.push(n); }); }));
/* 전투 드롭: 이능 몬스터는 슬라임, 제2구역부터는 마석도 가끔 */
DANGER_ZONES.forEach(z => z.terrains.forEach(t => t.monsters.forEach(m => {
  if (m.kind !== '이능 몬스터') return;
  if (!m.drops.some(d => d[0] === '슬라임')) m.drops.push(['슬라임', .22]);
  if (z.n >= 2 && !m.drops.some(d => d[0] === '마석')) m.drops.push(['마석', .1]);
})));

