  '이끼 위장 망토': { t: ['이끼 망토를 두르고 숲에 서자, 지나가던 짐승이 당신을 바위로 착각하고 지나갔다.', '망토 위로 이슬이 맺혔다. 숲과 하나가 된 기분이다.'], b: ['망토를 휘날리며 상대의 시선을 흐트러뜨렸다.'] },
