  ['요요', 'sports_baseball', '등급 F · 공격력 +5. 실을 감아 던지면 되돌아오는 금속 요요다. 생각보다 훨씬 아프다.', { slot: '무기', atk: 5, mods: { sen: 1 }, weapon: '요요', sell: 125 }]
