/* 장비 묘사 확장: kind t 이동 / b 전투 / g 채집 / i 조사. 슬롯·무기 종류마다 공통 문장을 두고, 아이템 전용 문장(EQUIP_LINES)은 더 자주 나온다 */
const WEAPON_KIND = { '중식도': '칼', '곡괭이': '곡괭이', '플라즈마 블레이드': '검', '아이스크림 소드': '검' };
const weaponKind = n => (ITEMS[n] && ITEMS[n].weapon) || WEAPON_KIND[n] || '';
const WEAPON_LINES = {
  '검': { t: n => [`허리의 ${n}이 걸음에 맞춰 규칙적으로 달그락거렸다.`], b: n => [`${n}을 비스듬히 세워 상대의 공세를 받아 흘렸다.`, `${n}의 날이 햇빛을 번쩍 받아 상대의 눈을 찔렀다.`], g: n => [`${n}으로 거치적거리는 덩굴을 쳐 냈다.`], i: n => [`${n}의 끝으로 바닥을 슬쩍 헤쳐 보았다.`] },
  '단검': { t: n => [`${n}을 손끝으로 빙글 돌리며 걸었다.`], b: n => [`${n}을 역수로 쥐고 빈틈 사이로 파고들었다.`], g: n => [`${n}으로 줄기를 깔끔하게 잘라 냈다.`], i: n => [`${n}으로 수상한 흔적을 조심스럽게 긁어 보았다.`] },
  '창': { t: n => [`${n}을 지팡이 삼아 짚으며 걸었다. 의외로 편하다.`], b: n => [`${n}을 길게 내질러 거리를 지켰다.`, `${n}의 자루를 비틀어 상대의 발을 걸어 넘겼다.`], g: n => [`${n} 끝으로 높은 가지의 열매를 쿡 찔러 떨어뜨렸다.`], i: n => [`${n}으로 풀숲을 휘저어 숨은 것이 없는지 확인했다.`] },
  '활': { t: n => [`${n}의 시위를 손가락으로 튕기자 맑은 소리가 났다.`], b: n => [`${n}을 힘껏 당겼다. 숨을 멈추고 시위를 놓았다.`], g: n => [`${n}을 곁에 내려놓고 부지런히 손을 놀렸다.`], i: n => [`${n}에 화살을 메겨 둔 채 주변을 천천히 살폈다.`] },
  '너클': { t: n => [`${n}을 끼운 주먹을 가볍게 쥐었다 펴며 걸었다.`], b: n => [`${n}을 낀 주먹으로 상대의 중심을 곧장 노렸다.`], g: n => [`${n}을 낀 채로 바위를 퍽퍽 두드려 깨뜨렸다.`], i: n => [`${n}으로 단단한 바닥을 두드려 속이 비었는지 확인했다.`] },
  '권총': { t: n => [`${n}의 안전장치를 한 번 더 확인하고 다시 집어넣었다.`], b: n => [`${n}의 총성이 짧게 울렸다.`], g: n => [`${n}을 허리에 단단히 매고 작업에 집중했다.`], i: n => [`${n}에 손을 얹은 채 조심스럽게 모퉁이를 돌았다.`] },
  '칼': { t: n => [`${n}을 허리춤에 꽂고 휘파람을 불며 걸었다.`], b: n => [`${n}을 크게 휘둘러 상대의 공격을 막아 냈다.`], g: n => [`${n}으로 재료를 슥슥 손질했다. 솜씨가 좋다.`], i: n => [`${n} 끝으로 이상한 흔적을 콕 찔러 보았다.`] },
  '곡괭이': { t: n => [`${n}을 어깨에 얹고 터덜터덜 걸었다.`], b: n => [`${n}을 내리찍자 땅이 쿵 울렸다.`], g: n => [`${n}을 힘껏 내리쳤다. 돌 부스러기가 사방으로 튀었다.`], i: n => [`${n}으로 바위를 톡톡 두드리며 속 소리를 들었다.`] },
  '채찍': { t: n => [`${n}을 허공에 가볍게 휘두르자 딱 소리가 났다. 새들이 놀라 날아올랐다.`, `${n}을 허리에 둘둘 감고 걸었다. 어쩐지 모험가가 된 기분이다.`], b: n => [`${n}이 허공을 가르며 상대의 발목을 휘감았다.`, `${n}을 휘두르자 공기가 찢어지는 소리가 났다. 상대가 움찔 물러섰다.`], g: n => [`${n}으로 높은 가지의 열매를 낚아채 끌어내렸다.`], i: n => [`${n}을 길게 뻗어 멀리 있는 물건을 끌어당겨 보았다.`] },
  '빗자루': { t: n => [`${n}에 슬쩍 걸터앉아 보았다. 당연히 뜨지는 않았다. 아직은.`, `${n}로 길을 쓸며 걸었다. 지나간 자리에 먼지 한 톨 남지 않았다.`, `누군가 ${n}를 타고 하늘을 날았다는 소문이 떠올랐다. 반신반의하며 자루를 쥐었다.`], b: n => [`${n}의 솔로 상대의 얼굴을 후려쳤다. 먼지가 확 일었다.`, `${n}의 자루를 빙글 돌려 상대의 공격을 튕겨 냈다.`], g: n => [`${n}로 잡초를 싹 쓸어 내자 재료가 드러났다.`], i: n => [`${n}로 낙엽을 쓸어 내자 땅바닥의 흔적이 드러났다.`] },
  '소총': { t: n => [`${n}을 가슴 앞에 비스듬히 메고 보폭을 맞춰 걸었다.`, `${n}의 멜빵을 한 번 고쳐 메자 묵직한 무게가 어깨에 자리 잡았다.`], b: n => [`${n}이 길게 불을 뿜었다. 탄피가 바닥에 후두둑 쏟아졌다.`, `${n}의 개머리판을 어깨에 단단히 붙이고 짧게 끊어 쏘았다.`], g: n => [`${n}을 등 뒤로 돌려 메고 두 손으로 작업했다.`], i: n => [`${n}의 가늠자 너머로 먼 곳의 움직임을 살폈다.`] },
  '주사기': { t: n => [`${n}를 허리춤에 꽂고 걸었다. 스쳐 가는 사람들이 슬금슬금 길을 비켰다.`, `${n}의 바늘 보호캡이 걸음마다 달그락거렸다.`], b: n => [`${n}를 들이밀며 외쳤다. "조금 따끔할 거예요!"`, `${n}의 피스톤을 꾹 눌렀다. 상대가 움찔하며 물러섰다.`], g: n => [`${n}로 나무 수액을 조심조심 뽑아 보았다.`], i: n => [`${n}의 끝으로 수상한 흔적을 콕콕 찔러 보았다.`] },
  '피처폰': { t: n => [`${n}을 접었다 폈다 하며 걸었다. 딸깍 소리가 은근히 중독적이다.`, `${n}의 안테나를 쭉 뽑아 보았다. 신호는 잡히지 않았다. 어째서인지 안심이 된다.`], b: n => [`${n}에 특정 번호를 누르자 몸이 눈부시게 빛났다. "변신!"`, `${n}을 높이 치켜들고 포즈를 잡았다. 상대가 잠시 멍해졌다.`], g: n => [`${n}의 손전등 불빛으로 손 위를 비추며 작업했다.`], i: n => [`${n}의 작은 화면 불빛으로 어두운 곳을 비춰 보았다.`] },
  '요요': { t: n => [`걸으면서 ${n}를 위아래로 돌렸다. 리듬이 발걸음과 맞아떨어진다.`, `${n}로 '개 산책시키기' 기술을 해 보았다. 아무도 보지 않아 다행이다.`], b: n => [`${n}를 던지자 실이 팽팽하게 당겨지며 상대의 이마를 정확히 쳤다.`, `${n}가 되돌아오며 상대의 옆구리를 한 번 더 쳤다.`], g: n => [`${n}의 실로 뿌리를 얽어 쑥 뽑아냈다.`], i: n => [`${n}를 멀리 던져 보고 되감으며 반응을 살폈다.`] }
};
const SLOT_LINES = {
  '얼굴': { t: n => [`${n}이(가) 바람을 막아 주어 한결 시야가 편했다.`], b: n => [`${n} 너머로 상대의 움직임을 놓치지 않았다.`], g: n => [`${n} 덕분에 작은 것까지 또렷하게 보였다.`], i: n => [`${n}을(를) 고쳐 쓰고 주위를 꼼꼼히 살폈다.`] },
  '머리': { t: n => [`${n}을(를) 고쳐 쓰자 따가운 햇볕이 한결 누그러졌다.`], b: n => [`${n}이(가) 스치는 일격을 막아 주었다.`], g: n => [`땀이 흐르는 이마를 ${n} 아래로 쓱 닦았다.`], i: n => [`${n}을(를) 눌러쓰고 주위를 두리번거렸다.`] },
  '상의': { t: n => [`${n}의 옷깃을 여미자 바람이 한결 잦아들었다.`], b: n => [`${n}이(가) 날아든 공격을 받아 냈다. 충격이 둔하게 전해진다.`], g: n => [`소매를 걷어 올리자 ${n}의 팔이 움직이기 편해졌다.`], i: n => [`${n} 소매로 먼지를 털어 내며 살폈다.`] },
  '하의': { t: n => [`${n}이(가) 걸음마다 사각사각 소리를 냈다.`], b: n => [`${n}이(가) 날렵한 움직임을 방해하지 않았다.`], g: n => [`쪼그려 앉아도 ${n}이(가) 불편하지 않았다.`], i: n => [`${n}에 묻은 흙을 툭툭 털며 일어났다.`] },
  '장갑': { t: n => [`${n}을(를) 낀 손으로 길가의 풀을 헤쳤다.`], b: n => [`${n}을(를) 꽉 쥐고 정면으로 주먹을 날렸다.`], g: n => [`${n}을(를) 낀 손이라 가시나 돌에 다칠 걱정이 없다.`], i: n => [`${n}을(를) 벗고 손끝으로 조심스럽게 더듬었다.`] },
  '신발': { t: n => [`${n}이(가) 땅을 단단히 움켜쥐고 발걸음을 이끌었다.`], b: n => [`${n}의 밑창이 땅을 박차고 나갔다.`], g: n => [`${n}으로 땅을 다지며 자리를 잡았다.`], i: n => [`${n}의 발끝으로 바닥을 슬쩍 쳐 보았다.`] },
  '가방': { t: n => [`${n} 속 짐들이 걸음에 맞춰 덜그럭거렸다.`], b: n => [`${n}을(를) 단단히 고쳐 메고 전투에 집중했다.`], g: n => [`${n}에 재료를 차곡차곡 갈무리했다.`], i: n => [`${n}에서 지도를 꺼내 대조해 보았다.`] }
};

/* ---------- 마이홈 (개인실 '마이홈': 도트 방에 가구를 자유롭게 놓는다) ----------
   방 좌표는 ROOM_W×ROOM_H 고정(화면에서는 창 크기에 맞춰 줄여 보여 준다). 격자·겹침 금지 없음, 가구는 정수 좌표(왼쪽 위 기준)로 저장한다.
   그리는 순서: 배경 → 벽지/바닥 → 벽 소품(layer 'wall') → 바닥 가구(layer 'floor'). 같은 층 안에서는 z(마지막으로 놓거나 누른 것이 가장 큼)가 위.
   가구 그림: 지금은 map(문자 도트)으로 만든 임시 그림. 직접 그린 PNG 는 src(+색을 바꿀 부분만 흰색으로 칠한 maskSrc)로 바꿔 끼우면 된다. */
const ROOM_W = 600, ROOM_H = 600, ROOM_MAX = 40, ROOM_SCALE = 4; // 방 창(배경) 크기 600×600. ROOM_SCALE: map 도트 1칸을 화면에서 몇 배로 그리는가
const ROOM_GEO = { // 이소메트릭 방 (가로 500 × 세로 400, 창 안에서 가운데): 바닥 마름모 + 뒤쪽 벽 두 면
  floor: [[50, 375], [300, 250], [550, 375], [300, 500]],
  left: [[50, 225], [300, 100], [300, 250], [50, 375]],
  right: [[300, 100], [550, 225], [550, 375], [300, 250]],
  wall: [[50, 225], [300, 100], [550, 225], [550, 375], [300, 250], [50, 375]] // 벽 두 면을 하나로 (가운데 모서리 선 없음)
};
const ROOM_BG_MAX = 100000, ROOM_BG_PX = 600; // 내 배경 이미지: 600×600 JPEG 으로 압축해 저장한 글자(100000자 이하). 서버 부담을 줄이려고 세이브에는 넣지 않고 따로 둔다
const ROOM_BG_RE = /^data:image\/(jpeg|webp|png);base64,[A-Za-z0-9+\/=]+$/;
const ROOM_TABS = ['벽지', '바닥', '침대', '의자', '책상', '수납', '소품', '벽소품', '배경'];
