function furnMap(w, h, ops) { // [['r', x, y, w, h, 글자], ['p', x, y, 글자]] 로 문자 도트 그림을 만든다
  const g = Array.from({ length: h }, () => Array(w).fill('.'));
  ops.forEach(o => { if (o[0] === 'r') { for (let y = o[2]; y < o[2] + o[4]; y++) for (let x = o[1]; x < o[1] + o[3]; x++) if (g[y] && g[y][x] !== undefined) g[y][x] = o[5]; } else if (g[o[2]] && g[o[2]][o[1]] !== undefined) g[o[2]][o[1]] = o[3]; });
  return g.map(r => r.join(''));
}
const FR = (x, y, w, h, c) => ['r', x, y, w, h, c];
const FURN = [];
const defFurn = (id, cat, name, desc, o) => { if (!FURN.some(f => f.id === id)) FURN.push({ id, cat, name, desc, layer: 'floor', ...o }); };
// 배경은 색으로만 만든 '꾸밈' (하나만 고른다). 벽지·바닥은 아래 ROOM_SKIN_PNG 그림만 쓴다
