/* ===== ROOM 가구 목록 (PNG) =====
   가구는 이 표에만 한 줄씩 추가하면 된다. 그림 파일은 assets/room/ 폴더에 넣는다 (자세한 방법: assets/room/README.md).
   [아이디, 분류, 이름, 설명, 옵션]   분류: '침대' '의자' '책상' '수납' '소품' '벽소품'
   옵션: layer:'wall'(벽에 거는 소품은 항상 바닥 가구 뒤), mask:true(색상변경이 되는 가구: <아이디>_mask.png 필요),
         scale(그림을 몇 배로 보여 줄지, 기본 1 — 작은 도트 그림은 4처럼 키운다), w·h(그림이 불러와지기 전 임시 크기)
   예) ['bed_basic', '침대', '기본 침대', '포근한 침대다.', { mask: true, w: 96, h: 78 }]  →  assets/room/bed_basic.png, bed_basic_mask.png
   분류를 '벽소품'으로 하면 layer 는 자동으로 'wall' 이다. */
const ROOM_FURNITURE = [
  ['bed_00', '침대', '기본 침대', '포근한 침대다.', { mask: true, w: 96, h: 78 }],
];
ROOM_FURNITURE.forEach(([id, cat, name, desc, o]) => { o = o || {}; defFurn(id, cat, name, desc, { src: `assets/room/${id}.png`, maskSrc: o.mask ? `assets/room/${id}_mask.png` : '', layer: o.layer || (cat === '벽소품' ? 'wall' : 'floor'), scale: o.scale || 1, w: o.w || 64, h: o.h || 64 }); });
/* ===== ROOM 벽지·바닥·배경 PNG (직접 그린 틀) =====
   모두 600×600 PNG 한 장. 방 무대와 같은 좌표라서 assets/room/_guide_room.png(안내선 그림)에 겹쳐 그리면 된다.
   벽지: 벽 두 면 자리에만 그리고 나머지는 투명 / 바닥: 바닥 마름모 자리에만 / 배경: 600×600 전체(불투명). 파일: assets/room/<아이디>.png
   [아이디, 분류('벽지'|'바닥'|'배경'), 이름, 설명]  — 자세한 방법: assets/room/README.md */
const ROOM_SKIN_PNG = [
  ['wall_00', '벽지', '기본 벽지', '보급품으로 주어지는 기본 벽지.'],
  ['floor_00', '바닥', '기본 바닥', '보급품으로 주어지는 기본 바닥.'],
];
const ROOM_SKIN_FALLBACK = { '벽지': { l: '#dcdcdc', r: '#dcdcdc' }, '바닥': { a: '#bdbdbd', b: '#aaaaaa' }, '배경': { a: '#ffffff', b: '#ffffff' } };
ROOM_SKIN_PNG.forEach(([id, cat, name, desc]) => { if (ROOM_SKIN_FALLBACK[cat]) defFurn(id, cat, name, desc, { skin: ROOM_SKIN_FALLBACK[cat], src: `assets/room/${id}.png` }); });
const furnDef = id => FURN.find(f => f.id === id);
const ROOM_DEFAULT_SKIN = { wall: 'wall_00', floor: 'floor_00', bg: 'b_white' };
const defaultRoom = () => ({ ...ROOM_DEFAULT_SKIN, zc: 0, items: [] });

/* '운동' 태그: 사냥(몬스터 처치)에서 떨어지는 물건. 운동 서브잡은 이 태그 물건만 납품받는다 (2026-10-25) */
{
  const drops = new Set(['짐승 고기', '짐승 가죽', '두꺼운 가죽']);
  DANGER_ZONES.forEach(z => z.terrains.forEach(t => [t.monster, ...(t.monsters || [])].forEach(m => (m && m.drops || []).forEach(([n]) => drops.add(n)))));
  drops.forEach(n => { const it = ITEMS[n]; if (it && !it.hidden && !(it.tags || []).includes('운동')) it.tags = [...(it.tags || []), '운동']; });
}

/* ---------- 2026-10-26: 쉬운 공방 레시피 · 공방/현지 조달/낚시 의뢰 ----------
   잘 오르지 않던 제작 숙련(재봉·목공·대장·가죽공예·보석공예·약학)은 숙련도를 CRAFT_MASTERY_MULT 배로 받고, 재료 2~3개로 금방 만드는 레시피가 하나씩 있다.
   본부 게시판에는 그 물건을 납품하는 '공방 의뢰'가 하루 WORKSHOP_DAILY 개, 각 구역 캠프에는 그 구역에서만 나는 재료·물고기를 찾는 의뢰가 하루 CAMP_DAILY 개 걸린다 (한국 시간 오전 4시에 바뀜). */
const CRAFT_MASTERY_MULT = { '재봉': 2, '목공': 2, '대장': 2, '가죽공예': 2, '보석공예': 2, '약학': 2 };
const EASY_RECIPES = [
  ['섬유 실타래', 'texture', '생체 섬유를 꼬아 만든 튼튼한 실타래다. 공방에서 늘 모자란다.', '재봉', { '생체 섬유': 2 }],
  ['나무 숟가락', 'restaurant', '나뭇가지를 깎아 만든 소박한 숟가락이다.', '목공', { '나뭇가지': 2 }],
  ['돌 망치', 'hardware', '돌과 나뭇가지로 엮은 간단한 망치다. 못 박기 정도는 충분하다.', '대장', { '돌': 2, '나뭇가지': 1 }],
  ['가죽 끈', 'link', '가죽을 가늘게 잘라 꼰 끈이다. 짐을 묶을 때 쓴다.', '가죽공예', { '가죽': 1 }],
  ['조개 장신구', 'brightness_7', '조개껍데기를 갈아 꿴 작은 장신구다.', '보석공예', { '조개껍데기': 2 }],
  ['약초 연고', 'healing', 'HP를 12 회복한다. 약초를 으깨 만든 간단한 연고다.', '약학', { '약초': 2 }]
];
EASY_RECIPES.forEach(([n, ic, desc, tag, mats]) => {
  const cost = Object.entries(mats).reduce((t, [m, q]) => t + q * ((ITEMS[m] ? ITEMS[m].sell : Math.min(...(MAT_GROUPS[m] || []).map(x => ITEMS[x].sell || 0))) || 0), 0);
  defItems(tag === '약학' ? '소모품' : '재료', [[n, ic, desc, { sell: Math.max(2, Math.floor(cost * .8)), tags: [tag], ...(tag === '약학' ? { use: { hp: 12 } } : {}) }]]);
  if (!RECIPES.some(r => r.out === n)) RECIPES.push({ out: n, mats, sec: 30, rank: 'F' });
  if (tag === '약학') MEDICINES.add(n); // 약초 연고는 '약' 분류
});
const WORKSHOP_DAILY = 2, CAMP_DAILY = 2;
const WORKSHOP_QUESTS = EASY_RECIPES.map(([n, , , tag]) => ({ id: `ws_${tag}`, board: '본부', kind: '서브', daily: 'ws', title: `공방 의뢰 · ${n}`, desc: `본부 공방에서 ${n} 3개를 납품받는다. (${tag} 레시피, 속성학습으로 배울 수 있다)`, need: { type: 'item', name: n, qty: 3, consume: true }, reward: { exp: 45, money: 130, items: [['응급 키트', 1]] } }));
QUESTS.push(...WORKSHOP_QUESTS);
const CAMP_QUESTS = {}; // 구역 → 그 구역 고유 의뢰 id 목록
DANGER_ZONES.forEach(z => {
  const other = new Set(); DANGER_ZONES.forEach(o => { if (o !== z) o.terrains.forEach(t => t.gather.forEach(g => other.add(g))); });
  const own = [...new Set(z.terrains.flatMap(t => t.gather))].filter(g => ITEMS[g] && !other.has(g));
  CAMP_QUESTS[z.id] = own.map(g => {
    const fish = (ITEMS[g].tags || []).includes('낚시') || ITEMS[g].group === '물고기', qty = fish ? 4 : 5, id = `cd_${z.n}_${g}`;
    QUESTS.push({ id, board: z.id, kind: '서브', daily: 'camp', title: fish ? `낚시 의뢰 · ${g}` : `현지 조달 · ${g}`, desc: fish ? `캠프 식당에서 이 구역에서만 잡히는 ${g} ${qty}마리를 찾는다.` : `캠프에서 이 구역에서만 나는 ${g} ${qty}개를 납품받는다.`,
      need: { type: 'item', name: g, qty, consume: true }, reward: { exp: 25 + 28 * z.n, money: 70 + 75 * z.n, items: [[z.n >= 4 ? '고급 응급 키트' : '응급 키트', 1]] } });
    return id;
  });
});
QUESTS.push({ id: 'daily_fish', board: '본부', kind: '서브', daily: true, title: '일일 의뢰 · 신선한 생선', desc: '식당에 붕어 4마리를 납품한다. (제1구역 호수 낚시)', need: { type: 'item', name: '붕어', qty: 4, consume: true }, reward: { exp: 30, money: 95, items: [['응급 키트', 1]] } });
DAILY_QUESTS.push(QUESTS[QUESTS.length - 1]);
const rotPick = (pool, n, salt, t = Date.now()) => { // 날짜(오전 4시 기준)마다 바뀌는 n개 고르기
  let a = ((todayIndex(t) + salt * 7919) * 2654435761) >>> 0; const rnd = () => { a = (Math.imul(a ^ (a >>> 15), 2246822507) + 1013904223) >>> 0; return a / 4294967296; };
  const p = pool.slice(); for (let i = p.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [p[i], p[j]] = [p[j], p[i]]; }
  return p.slice(0, Math.min(n, p.length));
};
/* 캠프가 둘인 구역은 캠프마다 다른 임무: 같은 날 2n개를 뽑아 캠프 순서(ci: campsOf 순서)대로 n개씩 나눈다 (목록이 모자라면 앞에서 다시) */
const campPick = (pool, n, salt, t, ci = 0) => { const p = rotPick(pool, n * 2, salt, t); return p.length >= n * 2 ? p.slice(ci * n, ci * n + n) : Array.from({ length: Math.min(n, pool.length) }, (_, k) => p[(ci * n + k) % p.length]); };
let boardDailyOk = (q, t, ci = 0) => q.daily === 'ws' ? rotPick(WORKSHOP_QUESTS.map(x => x.id), WORKSHOP_DAILY, 101, t).includes(q.id) : q.daily === 'camp' ? campPick(CAMP_QUESTS[q.board] || [], CAMP_DAILY, (DANGER_ZONES.find(z => z.id === q.board) || {}).n || 1, t, ci).includes(q.id) : dailyQuestIds(t).includes(q.id);

