/* 2026-10-29 사용처가 한 곳뿐이던 재료(사탕무·협곡 보리·설원 순무·사막 수박·초콜릿·광물 코어) 쓰임새 늘리기: 요리 4종 + 공방 의뢰 4개 */
defItems('소모품', [
  ['수박 화채', 'local_drink', 'HP를 6, 기력을 30 회복한다. 사막 수박을 사탕무 즙에 띄운 시원한 화채다.', { use: { hp: 6, sp: 30 }, tags: ['요리'], sell: 12 }],
  ['보리 순무죽', 'soup_kitchen', 'HP를 15, 기력을 30 회복한다. 협곡 보리와 설원 순무를 푹 끓인 죽이다. 속이 든든하다.', { use: { hp: 15, sp: 30 }, tags: ['요리'], sell: 12 }],
  ['초코 보리 쿠키', 'cookie', '기력을 36 회복한다. 볶은 보리 가루에 초콜릿을 섞어 구운 쿠키다.', { use: { sp: 36 }, tags: ['요리'], sell: 14 }],
  ['순무 샐러드', 'eco', 'HP를 18, 기력을 12 회복한다. 설원 순무와 사탕무를 얇게 썰어 허브로 버무린 샐러드다.', { use: { hp: 18, sp: 12 }, tags: ['요리'], sell: 12 }]
]);
RECIPES.push(
  { out: '수박 화채', mats: { '사막 수박': 1, '사탕무': 1, '수분 팩': 1 }, sec: 50, rank: 'E' },
  { out: '보리 순무죽', mats: { '협곡 보리': 1, '설원 순무': 1, '소금': 1 }, sec: 70, rank: 'E' },
  { out: '초코 보리 쿠키', mats: { '협곡 보리': 1, '초콜릿': 1, '알': 1 }, sec: 60, rank: 'E' },
  { out: '순무 샐러드', mats: { '설원 순무': 1, '사탕무': 1, '허브': 1 }, sec: 45, rank: 'E' }
);
{ const cost = rc => Object.entries(rc.mats).reduce((a, [n, q]) => a + q * ((ITEMS[n] ? ITEMS[n].sell : Math.min(...(MAT_GROUPS[n] || []).map(m => ITEMS[m].sell || 0))) || 0), 0); // 재료값보다 비싸게 팔리지 않게
  ['수박 화채', '보리 순무죽', '초코 보리 쿠키', '순무 샐러드'].forEach(n => { const rc = RECIPES.find(r => r.out === n); if (rc && ITEMS[n]) ITEMS[n].sell = Math.max(1, Math.min(ITEMS[n].sell || 1, Math.floor(cost(rc)))); }); }
[['사탕무', 3], ['협곡 보리', 3], ['설원 순무', 3], ['광물 코어', 1]].forEach(([n, q]) => {
  if (!ITEMS[n]) return; const id = `ws_m_${n}`; if (QUESTS.some(x => x.id === id)) return;
  const qq = { id, board: '본부', kind: '서브', daily: 'ws', title: `공방 의뢰 · ${n}`, desc: `본부 공방에서 ${n} ${q}개가 필요하다고 한다. 납품하면 보수를 준다.`, need: { type: 'item', name: n, qty: q, consume: true }, reward: { exp: 40, money: 120, items: [['응급 키트', 1]] } };
  WORKSHOP_QUESTS.push(qq); QUESTS.push(qq);
});

/* ===== 아이템 도트 아이콘 (assets/items/파일이름.png) =====
   한 줄 = '게임에 보이는 아이템 이름(띄어쓰기까지 똑같이)': '파일 이름(.png 빼고, 영어 소문자·숫자·_ 만)',
   - 16×16으로 그리면 소지품 칸·상점·레시피에서는 2배(32px), 작은 자리에서는 1배(16px)로 보인다.
   - 표에 없는 아이템, 파일이 없는 아이템은 원래 아이콘(defItems 두 번째 칸)이 그대로 나온다. */
