  '설원 순무 씨앗': 'seed_blue',
  '사막 수박 씨앗': 'seed_red',
  '정글 카사바 씨앗': 'seed_blue',
  '나뭇가지': 'branch',
  '돌': 'stone',
  '합금 파편': 'alloy_fragments',
  '흑요석': 'obsidian',
  '석재': 'building_stone',
  '점토': 'clay',
  '허브': 'herb',
  '협곡 허브': 'canyon_herb',
  '제1구역 캠프 신호기': '1_return_beacon',
  '제2구역 캠프 신호기': '2_return_beacon',
